pm.test("Status code name has string", function () {
    pm.response.to.have.status("OK");
});

const expected = {
    GET: [200, 206, 304],
    HEAD: [200],
    POST: [200, 201, 202],
    PUT: [200, 201, 204],
    PATCH: [200, 204],
    DELETE: [200, 202, 204],
    OPTIONS: [200, 204]
}[pm.request.method] || [200];

pm.test(pm.request.method + " returns " + expected.join("/"), function () {
    pm.expect(expected).to.include(pm.response.code);
});

// Takes the id from the JSON body, or the last segment of Location.
const location = pm.response.headers.get("Location") || "";
let id;
try {
    id = pm.response.json().id;
} catch (e) {}
if (id == null && location) id = location.split("/").filter(Boolean).pop();
if (id != null) pm.environment.set("resourceId", String(id));

pm.test("List is returned", function () {
    pm.response.to.have.status(200);
    const data = pm.response.json();
    pm.expect(Array.isArray(data)).to.equal(true);
    pm.expect(data.length).to.be.above(0);
});

// Put the value you send first, e.g. pm.environment.set("expectedName", "New name").
pm.test("Field was updated", function () {
    pm.expect(pm.response.json().name).to.eql(pm.environment.get("expectedName"));
});

// DELETE is idempotent: after it, the resource must answer 404.
pm.sendRequest(pm.request.url, function (err, res) {
    pm.test("Deleted resource returns 404", function () {
        pm.expect(err).to.equal(null);
        pm.expect(res.code).to.equal(404);
    });
});

pm.test("HEAD has headers only", function () {
    pm.response.to.have.status(200);
    pm.expect(pm.response.text()).to.equal("");
    pm.response.to.have.header("Content-Length");
});

pm.test("Allow header lists GET", function () {
    const allow = pm.response.headers.get("Allow") || pm.response.headers.get("Access-Control-Allow-Methods") || "";
    pm.expect(allow.toUpperCase()).to.include("GET");
});

pm.test("Body is equal to a string", function () {
    pm.expect(pm.response.text()).to.eql("response_body_string");
});

const json = pm.response.json();
pm.test("JSON value check", function () {
    pm.expect(json.value).to.eql(100);
});

const id = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    return (c === "x" ? r : (r & 0x3 | 0x8)).toString(16);
});
pm.variables.set("requestId", id);

if (!pm.environment.get("baseUrl")) {
    throw new Error("Set baseUrl in the active environment first");
}

pm.sendRequest("https://postman-echo.com/get", function (err, res) {
    if (err) { console.log(err); return; }
    console.log(res.json());
});

pm.sendRequest({
    url: "https://postman-echo.com/post",
    method: "POST",
    header: { "Content-Type": "application/json" },
    body: { mode: "raw", raw: JSON.stringify({ hello: "world" }) }
}, function (err, res) {
    if (err) { console.log(err); return; }
    pm.expect(res.code).to.eql(200);
});
